#!/usr/bin/env bash
set -euo pipefail

ROOT="$(git rev-parse --show-toplevel 2>/dev/null || pwd)"
cd "$ROOT"

if [ ! -d .git ]; then
  echo "Ошибка: command.sh нужно запускать из корня git-проекта."
  exit 1
fi

echo "[1/6] Сохраняю текущий код в backup-коммит..."
git add -A
if git diff --cached --quiet; then
  echo "Нет незакоммиченных изменений для backup-коммита."
else
  git commit -m "chore: backup current layout before bem refactor"
fi

echo "[2/6] Пушу backup-коммит..."
if ! git push origin HEAD; then
  git push -u origin HEAD || echo "Внимание: push backup-коммита не вышел. Изменения сохранены локально."
fi

echo "[3/6] Создаю BEM-патч..."
PATCH_FILE="$(mktemp)"
cat <<'B64' | base64 -d | gzip -dc > "$PATCH_FILE"
