echo "[4/6] Применяю изменения верстки и CSS..."
if ! git apply --3way --whitespace=nowarn "$PATCH_FILE"; then
  echo "Патч не применился автоматически. Возможно, файлы уже изменены или ты не в той версии проекта."
  echo "Патч лежит тут: $PATCH_FILE"
  exit 1
fi
rm -f "$PATCH_FILE"

echo "[5/6] Проверяю frontend, если зависимости установлены..."
if [ -d mdm-frontend ] && [ -d mdm-frontend/node_modules ]; then
  (cd mdm-frontend && npm run lint -- --max-warnings=0 || true)
  (cd mdm-frontend && npm run build || true)
else
  echo "node_modules нет — пропускаю npm-проверки. Потом выполни: cd mdm-frontend && npm install && npm run build"
fi

echo "[6/6] Коммичу и пушу BEM-рефактор..."
git add -A
if git diff --cached --quiet; then
  echo "Новых изменений после патча нет. Возможно, они уже применены."
else
  git commit -m "refactor: rewrite frontend layout with clean BEM classes"
fi

if ! git push origin HEAD; then
  git push -u origin HEAD || echo "Внимание: push BEM-коммита не вышел. Коммит сохранен локально."
fi

echo "Готово."
